style.css:
@-moz-document domain("roblox.com"), domain("www.roblox.com") {
/* Coloca a imagem como plano de fundo do site inteiro */
    body, html {
        background: url("https://iili.io/KYiLJDX.jpg")
                    no-repeat center center fixed !important;
        background-size: cover !important;
    }

    /* Deixa as áreas principais transparentes para o fundo aparecer */
    #container-main,
    #rbx-body,
    body > div:not(.navbar),
    body > div:not(#container-main) {
        background: transparent !important;
    }

    /* Remove a cor de fundo de caixas/painéis e adiciona leve transparência */
    [class*="content"],
    [class*="section"],
    [class*="container"],
    [class*="box"],
    [class*="panel"] {
        background: rgba(0,0,0,0.4) !important;   /* leve transparência para leitura */
        backdrop-filter: blur(4px);              /* desfoque opcional */
    }
}
